BEGIN TRANSACTION;
DROP TABLE IF EXISTS "Outlets";
CREATE TABLE "Outlets" (
	"outlet_id"	TEXT,
	"outlet_name"	TEXT,
	"outlet_type"	TEXT,
	"state"	TEXT,
	"lga"	TEXT,
	"monthly_sales_NGN"	INTEGER,
	"visit_freq_per_month"	INTEGER,
	"sku_count"	INTEGER,
	"oos_incidents_per_month"	INTEGER,
	"competitor_share_pct"	INTEGER,
	"outlet_active"	INTEGER,
	"sales_rep_id"	TEXT,
	"territory"	TEXT
);
COMMIT;
